INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(6500, 0, 65, 0, 0, 13, 'Dragonblight', 'The Dragonblight is the great white valley at the heart of southern Northrend, the place where dragons come when they are ready to die. Their bones lie across it in their thousands, and at its center rises Wyrmrest Temple, where the dragonflights meet in council under Alexstrasza the Life-Binder. The peace of that ancient graveyard is broken. Malygos''s blue dragonflight is tearing at the ley lines of the land, and the Scourge raises frost wyrms from the old bones and digs at the grave of Galakrond. In the north, Angrathar the Wrathgate bars the way into Icecrown, and before it the Alliance at Fordragon Hold and the Horde''s Kor''kron Vanguard prepare their assault. In the east the necropolis Naxxramas hangs above Wintergarde Keep, the Forsaken watch from Venomspite, and the Scarlet Onslaught has built a new Hearthglen on the coast. The Kalu''ak of Moa''ki, the homeless taunka and the Nerubians of Azjol-Nerub are caught in the middle of it all.', 'warcraft.wiki.gg/wiki/Dragonblight (dragon graveyard, Wyrmrest at the center, the dragonshrines, Galakrond''s remains, Naxxramas over Wintergarde, Wrathgate the barred entrance to Icecrown); npc_text 12713 (Tariolstrasz: the dragonflights confer amidst the bones of their ancestors); quest 12000 description (the blue dragonflight destroyed a ley line nexus); quest 12466 reward text (fuel for ten thousand frost wyrms in the bones); quest 12497 description (the Scourge unearthing Galakrond''s bones); quests 12224, 12474 (Kor''kron Vanguard and Fordragon Hold before the Wrathgate); quest 12235 description (Naxxramas sent down upon Wintergarde); npc_text 12575 (Ko''nani: the Kalu''ak caught in the middle); quest 12040 description (civil war in Azjol-Nerub)'),
(6501, 1, 65, 1, 0, 13, 'Coldwind Pass and Westwind', 'The only road from the Borean Tundra into the Dragonblight crosses a bridge at Coldwind Pass, where frozen elementals drift among the rocks and taunka braves keep watch for the caravans coming east. Wartook Iceborn waits at the bridge''s end to meet them. A little way on lies the Westwind Refugee Camp, a cluster of tents where the Horde shelters taunka who have lost their homes. Among the broken families walks Emissary Brighthoof, a tauren sent north to look after her winter cousins, whom the refugees have taken as an elder. Two wounded blood guards, Roh''kill and Tor''zin, nurse their pride: the caravan they guarded to the camp was ambushed by Anub''ar in the woods to the east.', 'quest 11930 description (Transborea the only way to the Dragonblight; Wartook waits across the bridge); zone_areas 4478: Wartook Iceborn 26156, Taunka''le Brave 26157, Frozen Elemental 25715; zone_areas 4151: Taunka''le Refugees, Emissary Brighthoof 26181, Blood Guards Roh''kill 26180 and Tor''zin 26182; quest 11977 description (the tribe took her as a village elder); quest 11980 description (caravan ambushed, the two guards barely escaped); npc_text 12627 (Brighthoof)'),
(6502, 1, 65, 2, 0, 13, 'Moa''ki Harbor', 'Moa''ki Harbor is the home of the Dragonblight Kalu''ak, tuskarr ruled by their chieftain, Elder Ko''nani. Turtle riders carry travelers between its docks and their kin at Unu''pe and Kamagua, and envoys of the Alliance and the Horde both wait on the elder. The harbor is not at peace. A great upheaval has just torn the land, and the wolvar of Snowfall Glade, crowded onto the glade to the north since outsiders came, raid the stores the Kalu''ak need for a journey whose end they do not yet know. Ko''nani speaks of the Dark One riding forth again and of the dragons'' Nexus War. Trapper Mau''i holds that the wolvar have as much right to live as his own people.', 'npc_text 12575 (Ko''nani: the Dark One and his San''layn, the Nexus War, vrykul reawakened, two ambassadors, a safe haven); creature_template 26194 subname (Chieftain of the Dragonblight Kalu''ak); quest 11958 description (wolvar forced onto the glade by your peoples; upheaval this morning; the trek from our home); quests 11995 and 11996 (Emissary Skyhaven and Envoy Ripfang at the harbor); zone_areas 4152: Moa''ki Turtle Rider 29953, Moa''ki Warrior, Tua''kea Crab Traps; quests 12117 and 12118 (word from Moa''ki carried from Unu''pe and Kamagua); howling_fjord.json 49520 and borean.json 353704 (the sea links); quest 11960 description (Mau''i: the wolvar have as much right to exist; prev 0, open setting)'),
(6503, 1, 65, 3, 0, 13, 'Indu''le Village', 'Indu''le was a Kalu''ak village on the high bluffs above Lake Indu''le, and Moa''ki has heard nothing from it since the ground shook and tore apart. What is left is a place of ghosts and madness. The spirits of its fishermen, warriors and mystics still walk the huts, and the villagers who lived through it wander among them out of their minds, attacking anyone who comes near. In the northwest corner stands the stone statue of Elder Mana''loa, one of the stone elders the tuskarr revere as fonts of ancient wisdom. Below, the lake itself has gone wrong: angry elementals churn in its waters.', 'quest 12028 description (nothing heard since the ground shook and was torn apart); quest 12030 description (the stone elders, revered as fonts of ancient wisdom; Mana''loa in the northwest corner); quest 12125 description (Indu''le on the high bluffs; the tuskarr gone mad); zone_areas 4153: Deranged Indu''le Villager 26411, Indu''le Fisherman/Warrior/Mystic, gameobject 188419 Elder Mana''loa; 4166: Corrupted Rager 21223'),
(6504, 1, 65, 4, 0, 13, 'Moonrest Gardens', 'Moonrest Gardens, in the far west of the Dragonblight, was the final resting place of a noble company of Highborne elves, and it lay on a ley line nexus. The blue dragonflight''s mage hunters came with a giant device that now floats in the sky above the ruins, the Surge Needle, and bored a great pit into the gardens. The dead did not rest. The ghosts of the Highborne rose and slew half the mage hunters, whose bodies lie among the stones, and their spirits still prowl the ruins. Ethenial Moonshadow demands vengeance on the defilers. South of the gardens, more mage hunters hold the Glittering Strand.', 'quest 12000 and 11999 descriptions (resting place of Highborne; ley line nexus; surge needle; the ghosts decimated half the mage hunters); quest 12006 description (Ethenial: avenge us); quest 12013 description (the device in the sky bored a pit); quest 12065 description (mage hunters on the Glittering Strand); zone_areas 4157: Moonrest Highborne 26455, Dead Mage Hunter 26477, Ethenial Moonshadow 26501, Surge Needle Sorcerer'),
(6505, 1, 65, 5, 0, 13, 'Stars'' Rest', 'Stars'' Rest is the Alliance''s outpost in the west of the Dragonblight, held by night elves under Commander Saia Azuresteel with Sentinels on its paths. Its heart is a moonwell, from which Warden Jodi Moonsong draws the liquid fire of Elune to cleanse the beasts the Scourge has tainted around Icemist to the north. Palena Silvercloud keeps hippogryphs for riders, Sarendryana grieves for the ancients of the Lothalor Woodlands, and an image of Archmage Modera of the Kirin Tor speaks for Dalaran here, watching the blue dragonflight''s work in the west.', 'warcraft.wiki.gg/wiki/Stars''_Rest (night elf outpost); zone_areas 4158: Stars'' Rest Sentinel 26448, Saia Azuresteel 26459, Jodi Moonsong 26973, Palena Silvercloud 26881, Sarendryana 26837, Image of Archmage Modera 26673; quest 12166 description (liquid fire of Elune from the moonwell; the Scourge moved into Icemist); quest 12092 description (Sarendryana and the ancients); quest 11995 (Modera at Stars'' Rest)'),
(6506, 1, 65, 6, 0, 13, 'Lothalor Woodlands', 'The Lothalor Woodlands, between Stars'' Rest and Agmar''s Hammer, are the home of ancients, the most majestic of Northrend''s children. The magic loosed across the land has reached them. Arcane wyrms have risen out of the ground and swarm through the trees, and some of the ancients have been corrupted and now strike at anything that moves. Only the treants of the woods seem untouched by it. Above the forest, mage hunters of the blue dragonflight guard another of their ley line foci, commanded by a troll lieutenant named Ta''zinni.', 'quests 12092 and 12096 descriptions (ancients corrupted by arcane wyrms risen from the ground; treants immune); quest 12092 reward text (the most majestic of Northrend''s children); quest 12083 description (a focus atop the woodlands); zone_areas 4160: Arcane Wyrm 26322, Lothalor Ancient 26321, Corrupted Lothalor Ancient 26333, Woodlands Walker 26421, Lieutenant Ta''zinni 26815, Focus Wizard'),
(6507, 1, 65, 7, 0, 13, 'Icemist Village and the Pit of Narjun', 'Icemist Village, at the foot of the mountains west of Agmar''s Hammer, was the capital of the taunka. Now it belongs to the Anub''ar, undead Nerubians of Azjol-Nerub. Their slayers and cultists fill the village, the cultists'' suits leaking fumes that poison everything around them, and they are building an army of winged blightbeasts. In the middle of the village a taunka prisoner hangs in magical chains, cursing his captors. To the west gapes the Pit of Narjun, a vast sinkhole from which the Anub''ar marched to raze Icemist, and in its depths Nerubians who refuse the Lich King fight on.', 'quest 12053 description (Icemist west of Agmar''s Hammer at the foot of the mountains); quest 11979 description (capital city of the taunka); quest 12034 description (the Pit of Narjun, exit point of Azjol-Nerub''s undead armies; the Anub''ar razed Icemist); quest 12167 description (fumes from the cultists'' suits); quest 12072 description (blightbeasts being constructed); creature_text 26654 groups 0 (Release me, fiends!); quest 12040 description (Kilix: civil war); zone_areas 4163: Anub''ar Slayer, Cultist, Blightbeast, Roanauk Icemist 26654, Anub''ar Prison'),
(6508, 1, 65, 8, 0, 13, 'Agmar''s Hammer', 'Agmar''s Hammer, a fortress of black, jagged metal in the west of the Dragonblight, is the Horde''s testament to its power here, and Overlord Agmar rules it from his throne in Hellscream''s name. Kor''kron guards walk its walls, Valnok Windrager''s war riders circle above, and Captain Gort hunts traitors in its ranks. An image of Archmage Aethas Sunreaver speaks for the Kirin Tor beside the throne. Forsaken apothecaries under Doctor Sintar Malefious work in their own corner, to the disgust of Earthwarden Grife, and the unbound death knight Koltira Deathweaver has taken up residence for a time. Old Borus Ironbender, a smith of fifty years, broods over the Wrathgate''s strange metal, which he swears he has seen breathe.', 'quest 12221 description (black, jagged metal orc buildings); quest 12008 description (testament to the Horde''s power); npc_text 13003 (Agmar: from this throne I issue the command of Hellscream); zone_areas 4165: Kor''kron Windrager, Valnok Windrager 26574, Captain Gort 26618, Image of Aethas Sunreaver 26471, Doctor Sintar Malefious 26505, Earthwarden Grife 26854, Koltira Deathweaver 26581, Borus Ironbender 26564; npc_text 12699 (Grife: these Forsaken fools); quest 12115 description (an unbound death knight has temporarily taken residence); quest 12039 description (Borus: fifty years, never seen metal breathe)'),
(6509, 1, 65, 9, 0, 13, 'Wyrmrest Temple', 'Wyrmrest Temple, said to have been raised by the titans, stands at the center of the Dragonblight, and here the dragonflights confer in peace amidst the bones of their honored ancestors. It is the seat of the Wyrmrest Accord. Alexstrasza the Life-Binder holds court at its summit with her consort Krasus, beside Lord Itharius of the green flight, Chromie of the bronze, and Nalice of the black, who sneers at all of them and says they would never dare attack her there. Drakes carry visitors between its terraces, and the Alliance and the Horde each keep an ambassador at its foot. The peace has been broken: the blue dragonflight has launched a surprise attack on the temple itself.', 'warcraft.wiki.gg/wiki/Dragonblight (Wyrmrest believed built by the titans); npc_text 12713 (Tariolstrasz: dragonflights confer in peace; the blue surprise attack); npc_text 12942 (Nalice); quest 12266 reward text (Nalice); zone_areas 4254: Alexstrasza 26917, Krasus 27990, Lord Itharius 27785, Chromie 27856, Nalice 27765, Torastrasza 26949, Tariolstrasz 26443, Lauriel Trueblade 27803, Golluck Rockfist 27804; npc_text 12714 (drakes between the terraces)'),
(6510, 1, 65, 10, 0, 13, 'The Ruby Dragonshrine', 'West of Wyrmrest, in a ring of scarred canyons, lies the Ruby Dragonshrine of the red dragonflight, a sacred place where a great tree drops ruby acorns and the ruby lilac grows. The Scourge has overrun it. Frigid necromancers work inside, the red wyrms that fell defending it rise again as skeletal emberwyrms, and ghouls, geists and abominations pour out through the canyons. Ruby keepers and guardians hold the ridges with the help of a regiment from each of the Alliance and the Horde. The shrine''s keeper, Dahlia Suntouch, is nowhere to be found.', 'quests 12416 and 12448 descriptions (shrine overrun, Dahlia missing, emberwyrms, regiments under Captain Iskandar and Captain Drayzen); quest 12417 description (ruby acorns from the tree); quest 12102 description (ruby lilac); quests 12460 and 12461 (Ceristrasz and Vargastrasz on the ridges; west of Wyrmrest); zone_areas 4168: Frigid Necromancer, Ruby Keeper 27530, Ruby Guardian 27725, Frigid Abomination/Geist Attacker, Dahlia Suntouch 27680, Emberwyrm 26286, Ruby Acorn, Ruby Lilac'),
(6511, 1, 65, 11, 0, 13, 'The Obsidian Dragonshrine', 'Northwest of Wyrmrest and just west of the Wrathgate, the Obsidian Dragonshrine of the black dragonflight smolders among the bones of its dead. The Cult of the Damned has come here too: necrolytes and their burning skeletons crowd the approach, and deeper in, in the cave called the Maw of Neltharion, the cultists draw power from the bones of fallen black dragons. One black dragon has come to deal with them, Serinar, who has played his part in destroying whole civilizations and is disgusted to stoop to the cult. At Wyrmrest, the black ambassador Nalice mocks the red flight for saving only its own shrine.', 'quest 12447 description (Nalice: the red flight''s good graces don''t extend to the other shrines; the shrine northwest of Wyrmrest, west of the Wrath Gate); quest 12261 description (drawing power from the bones of my dead brothers); npc_text 12850 (Serinar); zone_areas 4167: Smoldering Skeleton 27360, Burning Depths Necrolyte 27356, Magmawyrm 26475; quest 12263 (the Maw of Neltharion)'),
(6512, 1, 65, 12, 0, 13, 'The Emerald Dragonshrine', 'On the southern shore of the Dragonblight lies the Emerald Dragonshrine, the garden of Ysera, kept by the green dragon Nishera. It is a living place among the bones: emerald lashers grow in it, great skytalons guard the sky above it, and green dragons are said to weep before they die, leaving hardened tears scattered through the shrine. Nishera warns visitors to watch their step, for things in the garden are not always as they seem. Even its defenders now treat outsiders as enemies.', 'quest 12200 description (dragon tears; green dragons cry before they die); npc_text 12758 (Nishera: the garden of Ysera; things are not always as they seem); quest 12454 description; zone_areas 4179: Emerald Lasher 27254, Emerald Skytalon 27244, Emerald Dragon Tear, Nishera 27255'),
(6513, 1, 65, 13, 0, 13, 'The Bronze Dragonshrine', 'In the east of the Dragonblight lies the Bronze Dragonshrine, and it is hidden in a storm of time. The storm keeps immortals out, and inside it the Infinite Dragonflight, strange bronze dragons of uncertain origin, battles the shrine''s defenders for control of it. Chromie, the bronze flight''s ambassador at Wyrmrest, has a plan: mortals can cross into the storm where her kind cannot, and with the Hourglass of Eternity they might learn who leads the Infinite.', 'quest 12470 description (time storm keeps immortals out; Infinite fight the defenders to wrest control); npc_text 12976 (Chromie); zone_areas 4175: Tempus Wyrm, Infinite Eradicator 32185, Infinite Timebreaker 32186, Bronze Shrine Warden'),
(6514, 1, 65, 14, 0, 13, 'Galakrond''s Rest', 'North of Wyrmrest lie the dying grounds of Galakrond, the progenitor of dragonkind, whose bones are larger than all the Aspects together. The Scourge is digging them up. Scavengers labor day and night in the snow, rotting storm giants and frost wyrms guard the digs, and from the ridge of the Wicked Coil above them, Grand Necrolord Antiok rides the shoulders of Thiassi the Lightning Bringer, a reconstructed storm giant lord, and drives his workers on. His voice carries far: the Lich King, he shouts, demands more frost wyrms for Angrathar, and soon the bones of Galakrond will rise.', 'quests 12495 and 12496 reward text (Alexstrasza: dying grounds of Galakrond, progenitor of dragonkind, larger than all the Aspects combined); quest 12497 description (Antiok atop the Wicked Coil on Thiassi; unearthing the bones day and night); creature_text 28006 group 2 (Antiok''s yells); zone_areas 4173: Wastes Scavenger 28005, Rotting Storm Giant 27270, Reanimated Frost Wyrm 26841; 4174: Thiassi the Lightning Bringer 28018; quest 12044 description (Xink: the Scourge digging up some ancient dragon thing)'),
(6515, 1, 65, 15, 0, 13, 'Nozzlerust Post and the Crystal Vice', 'In the north of the Dragonblight the goblins of Nozzlerust Post have found a war to profit from. Narf, Xink and Zivlix sell to anyone with coin: ore lifted from the Scourge digs, jormungar meat for hungry troops, lumber for the Alliance''s towers, explosives carried by runners to the Wrathgate, when the harpies of Coldwind Heights do not catch them first. In the Crystal Vice to the northeast, crystalline ice giants under Ko''char the Unbreakable shelter from the dragons and fight jormungar that rise from the cavern below to eat them. Narf''s brother Zort is there too, hoping to talk the giants into dying for the goblins.', 'quests 12044, 12049, 12050, 12469 descriptions (ore for the Horde''s weapons, meat for troops, lumber for Alliance towers, explosives runner bound for the Wrath Gate killed by harpies); quest 12052 description (harpies attacking shipments to the gate); quest 12112 description (Zort, Narf''s brother, conning the giants); npc_text 12706, 12707 (Zort; Ko''char); quest 12079 description (the jormungar eat his brothers); zone_areas 4396, 4230, 4187: Narf 26647, Xink 26660, Zivlix 26661, Mistress of the Coldwind 26578, Crystalline Ice Giant 26291, Ko''char 26473, Zort 26659, Rattlebore 26360'),
(6516, 1, 65, 16, 0, 13, 'Fordragon Hold', 'Nestled against the mountain in the north of the Dragonblight, Fordragon Hold is the Alliance''s base of operations against Angrathar the Wrathgate, and Highlord Bolvar Fordragon commands it in person. The hold is still being built around him: carpenters, masons and lumberjacks raise its walls while footmen drill at practice dummies. Knights and battle mages, marksmen and gryphon riders muster for the assault on the gate, and medics tend the wounded.', 'quest 12474 description (nestled against the mountain in northern Dragonblight; our base of operations); zone_areas 4169: Highlord Bolvar Fordragon 27872, Fordragon Carpenter/Mason/Lumberjack/Footman/Marksman/Knight/Battle Mage/Gryphon Rider/Medic, Wounded Fordragon Soldier, Practice Dummy'),
(6517, 1, 65, 17, 0, 13, 'The Kor''kron Vanguard', 'The Kor''kron Vanguard is the Horde''s camp before the Wrathgate, the elite of the Warchief''s guard come to break the Lich King''s door. Kor''kron and Warsong elites, Darkspear spear throwers, taunka huntsmen and windfuries muster among war kodos and battle wyverns while peons keep the camp standing. Their commander is Saurfang the Younger, son of High Overlord Varok Saurfang. His father has gifted him his own battle armor and axe, and he means to put them to good use soon.', 'zone_areas 4170: Kor''kron Vanguard 27553, Warsong Elite 27557, Darkspear Spear Thrower 27560, Taunka Windfury 27571, Taunka Huntsman 27573, War Kodo, Kor''kron Battle Wyvern, Warsong Peon, Saurfang the Younger 25257; npc_text 12777 (my father has gifted me with his battle armor and axe); quest 12224 description (the son of Saurfang at the Kor''kron Vanguard); page_text 3069 (the Warchief has sent his elite guard)'),
(6518, 1, 65, 18, 0, 13, 'Angrathar the Wrathgate', 'Angrathar the Wrathgate is the barred entrance to Icecrown, a vast gate set into the mountains at the northern edge of the Dragonblight. The metal that holds it together pulses and shifts as if it were alive; old smiths swear they have seen it breathe. Before it lies the Court of Skulls, where the Alliance and the Horde fight side by side against the Scourge that pours out to meet them: aberrations, frail constructs and colossal abominations, plague eruptors, frenzied gargoyles and the necrolords who drive them. Frost wyrms strafe the field from above.', 'warcraft.wiki.gg/wiki/Dragonblight (the barred entrance to Icecrown); quest 12039 description (the gate''s metal pulsed and undulated; never seen metal breathe); quest 12474 reward text (the Wrathgate made of the strange ore); zone_areas 4171/4172: Angrathar Aberration 27631, Frail Construct 27604, Colossal Abomination 27605, Plague Eruptor 27611, Frenzied Gargoyle 27691, Angrathar Necrolord 27603, Fordragon and Kor''kron soldiers; quest 12495 description (frost wyrms strafe the field)'),
(6519, 1, 65, 19, 0, 13, 'Wintergarde', 'Wintergarde Keep holds the eastern border of the Dragonblight, the 7th Legion''s fortress, and above it hangs the necropolis Naxxramas. The village that once lay below the keep is gone. Its ruins are now the Carrion Fields, a breeding ground of the Scourge, where plague wagons roll, siegesmiths build their engines and the hungering dead wander in their hundreds. Geists haunt the town square, the dead rise from the crypt, the mine has been lost, and risen gryphon riders strike from the sky. From Thorson''s Post across the fields, the Legion''s steam tanks wait for the order to advance.', 'quest 12235 description (Naxxramas sent down upon us; the lower village lost); quest 12237 description (ruins of Wintergarde Village, now known as the Carrion Fields); quest 12253 description (geists in the town square); quest 12309 description (undead from the ruins and the town crypt); quest 12269 description (the mine lost); npc_text 12823 (risen gryphon riders); quest 12325 description (Thorson''s Post); zone_areas 4177/4188/4190: 7th Legion, Vengeful Geist, Plague Wagon, Scourge Siegesmith, Hungering Dead, Alliance Steam Tank, Duke August Foehammer; warcraft.wiki.gg/wiki/Wintergarde_Keep (7th Legion and Valiance Expedition)'),
(6520, 1, 65, 20, 0, 13, 'New Hearthglen', 'On the cliffs of the southern coast, below Venomspite, the Scarlet Onslaught has built a new Hearthglen. It has walls and barracks, an abbey with a bell tower, a chapel, a smithy, stables and a lumbermill, and ballistae line its walls. Footmen and raven priests fill its streets, Forsaken prisoners rot in its cages, and the torturer LeCraft works in the barracks'' basement. At Crusader''s Landing below lies the Sinner''s Folly, the Onslaught''s flagship. High General Abbendis commands the town, with an admiral of the Scarlet Fleet named Barean Westwind close at hand.', 'warcraft.wiki.gg/wiki/Dragonblight (Scarlet Onslaught at New Hearthglen); quests 12234, 12252, 12273, 12283 descriptions (abbey, barracks next to the smithy, chapel, lumbermill, stables, the general''s house); quest 12232 (ballistae); zone_areas 4180: Onslaught Footman 27203, Raven Priest 27202, Forsaken Prisoner, Torturer LeCraft 27209, High General Abbendis 27210, Admiral Barean Westwind 27951; 4181: Captain Shely 27232; creature_template 27951 subname (Grand Admiral of the Scarlet Fleet); page_text 3092 (the Sinner''s Folly her flagship)'),
(6521, 1, 65, 21, 0, 13, 'Venomspite', 'Venomspite is the Forsaken town in the east of the Dragonblight, on the south side of the mountain, where Vengeance Pass leads north to the Carrion Fields. High Executor Wroth commands it and has decreed death for every member of the Scarlet Onslaught to the south. Chief Plaguebringer Middleton runs its laboratory, promising to ravage the living, or rather, he corrects himself, the Scourge. Spy Mistress Repine runs agents, Apothecary Vicky Levine keeps starved rats, blight spreaders wait at the gate, and Quartermaster Bartlett complains that the Kor''kron at the Wrathgate have taken every coin in the coffers.', 'quest 12488 description (Venomspite on the south side of the mountain, southeast of the Dragon Wastes); quest 12218 description (Vengeance Pass to the Carrion Fields); quest 12205 description (Wroth''s decree); npc_text 12751 (Middleton); zone_areas 4186: High Executor Wroth 27243, Middleton 27172, Spy Mistress Repine 27337, Vicky Levine 27248, Forsaken Blight Spreader 26523, Quartermaster Bartlett 27267; quest 12211 description (starved rats); quest 12303 description (the Kor''kron Vanguard took all our coin)'),
(6522, 1, 65, 22, 0, 13, 'The Forgotten Shore', 'On the southeastern coast the Forgotten Shore is strewn with broken ships whose crews never left, and above the beach stand the ruins of an old Alliance base. Ghostly peasants, riflemen, footmen, knights and captains of the Alliance walk the beach and the waters off it, soldiers who have not understood that they are dead, crying out against a betrayal and a prince who gave them his word. Treasure still lies among the wrecks. Nearby at Dawn''s Reach the Argent Crusade has made camp to quell the damned souls trying to escape Wintergarde, and the Forsaken of Venomspite eye the shore as a site for a new mausoleum.', 'quest 12290 description (spirits of the damned, once brave soldiers of the Alliance, bound to this world); quest 12304 description (human ghosts who haven''t realized they''re dead; a new mausoleum); quest 12303 description (treasure among the wrecks); creature_text 27224, 27225 (You gave us your word, betrayer! Our prince has forsaken us!); quest 12287 reward text (Orik and Tilda at Dawn''s Reach, sent to quell the damned souls attempting to escape Wintergarde); zone_areas 4185: Forgotten Peasant/Rifleman/Footman/Knight/Captain, Forgotten Treasure; 4233: Orik Trueheart 27347, Tilda Darathan 27348; quest 12301 description (the ruins of Orik''s old base on the upper reaches of the beach)'),
(6523, 2, 65, 1, 0, 13, 'Alexstrasza the Life-Binder', 'Alexstrasza the Life-Binder, Aspect of the red dragonflight, is the Queen of the Dragons, and from the summit of Wyrmrest Temple she leads the Wyrmrest Accord. She greets mortals as friends and tells them she has known them since before they were born. She abhors the loss of any life, yet her flight is at war on every side: Malygos has turned his blue dragons against the world''s magic and against the temple itself, and the Scourge defiles the shrines and the bones of her kind. Mortals who reach her bring news, and ask her leave.', 'creature_template 26917 (Queen of the Dragons); npc_text 14138 (greetings); quest 12123 completion text (I have known you since before you were born); quest 12435 description (I abhor the loss of life); npc_text 12713 and 12887 (the blue attack on the temple); quest 12495 description (permission to defile the bones); warcraft.wiki.gg/wiki/Wyrmrest_Accord (she founded it)'),
(6524, 2, 65, 2, 0, 13, 'Korialstrasz', 'Korialstrasz is Alexstrasza''s consort, and at Wyrmrest he stands beside her in the form he wore for years among the mages of Dalaran: Krasus, an elder of the Kirin Tor who sat on its ruling council. When the Dragonmaw held his queen captive in Grim Batol, it was he who worked to see her freed. Now the Scourge has overrun the Ruby Dragonshrine of his flight, and he calls on every ally he has to save it.', 'creature_template 27990 (Krasus, Consort of the Queen); warcraft.wiki.gg/wiki/Korialstrasz (Krasus of the Kirin Tor and its ruling council, citing Day of the Dragon, 2001; his part in freeing Alexstrasza from Grim Batol, Day of the Dragon); quests 14444 and 24555 (patch 3.3: Korialstrasz, better known as Krasus, long a friend of the Kirin Tor); quest 12447 description (Korialstrasz calls upon his allies to save the Ruby Dragonshrine); wetlands.json 1115 (Alexstrasza held in Grim Batol)'),
(6525, 2, 65, 3, 2, 13, 'Overlord Agmar', 'Overlord Agmar, commander of the Kor''kron in the Dragonblight, issues Hellscream''s commands from the throne of Agmar''s Hammer: his word, he says, is life and death. Two great worgs, Gar''mak and Lak''tuk, lie at his feet, and he trusts almost no one. Every letter in the Hammer passes through his hands before it is sent, for there are spies and traitors everywhere, and his wanted posters prove it: a mage commander of his own who went over to the blue dragonflight is marked for death beside the beasts that prey on his caravans. His eyes are on Angrathar.', 'npc_text 13003 (from this throne I issue the command of Hellscream); creature_template 26379 subname (Kor''kron Commander); zone_areas 4165: Lak''tuk 26380, Gar''mak 26381 beside him; quest 12085 completion text (all mail goes through me first; spies and traitors); page_text 3069 (Agmar demands all mail be read); quests 12089-12091 (wanted posters by decree of Overlord Agmar); quest 12008 reward text (armies amassing at the foot of the Wrathgate)'),
(6526, 2, 65, 4, 0, 13, 'Kilix the Unraveler', 'Kilix the Unraveler is a Nerubian of Azjol-Nerub who has not bowed to the Lich King, and he waits in the depths of the Pit of Narjun with a few battleguards. His kingdom is at war with itself. At the heart of the world, he says, the last living members of his species defend themselves against total annihilation, for the Lich King means to rule Azjol-Nerub at any cost, and those who will not yield are branded enemies of the Scourge and marked for death. He warns that the Pit is no place for the meek, and offers the Horde a common enemy in Arthas.', 'quest 12040 description and completion text (civil war; the last living members of my species; the Azjol Empire will rise again); npc_text 14216 (no place for the meek); zone_areas 65 near the Pit: Kilix 26653, Azjol-anak Battleguard 26662; creature_template 26653 faction 2016 (neutral to both factions)'),
(6527, 2, 65, 5, 1, 13, 'High Commander Halford Wyrmbane', 'High Commander Halford Wyrmbane leads the 7th Legion at Wintergarde Keep. His soldiers are the nameless, faceless sons and daughters of the Alliance who fought through Mount Hyjal, the sands of Silithus and the armies of the Legion, and he holds that the first strike belongs to them and the last strike is all their enemies see. A plain-spoken soldier, he means to rebuild and fortify Wintergarde under the shadow of Naxxramas, and then to send reinforcements to Lord Fordragon at the Wrathgate.', 'npc_text 12739 (the 7th Legion creed); quest 12251 reward text (get the town built up and fortified; reinforcements for Lord Fordragon); warcraft.wiki.gg/wiki/Wintergarde_Keep (Halford led the defense)'),
(6528, 2, 65, 6, 0, 13, 'High General Abbendis', 'High General Abbendis led the Scarlet Crusade in the Scarlet lands of Lordaeron and somehow survived the attacks upon Tyr''s Hand. She brought a small force north, and on the coast of the Dragonblight founded New Hearthglen as the stronghold of the Scarlet Onslaught. Her soldiers carry copies of The Path of Redemption, said to hold her prophetic ramblings. Commander Eligor Dawnbringer of Wintergarde calls her his old enemy and believes she is far too shrewd an opponent to leave alive: whatever use her zealots might be against the Scourge, he is sure she will be at the Alliance''s throat before the dust settles.', 'scarlet_enclave.json 429824 (High General of the Scarlet Crusade); quest 12464 description (my old enemy; survived the attacks upon Tyr''s Hand; a small force north; New Hearthglen); quest 12477 description (The Path of Redemption, her prophetic ramblings); quest 12283 description (the general''s diary); creature_template_model 27210 display 24413, creature_model_info gender 1 (female); quests 12283, 12285, 12464 call her ''her'''),
(6529, 3, 65, 1, 2, 13, 'Into the Fold', 'The Horde means to bring the taunka into its ranks, and a tauren, Emissary Brighthoof, waits among the refugees at Westwind to welcome them into the fold. She will not send them out defenseless. The armaments meant for the Horde''s newest members were lost when the Anub''ar ambushed a caravan from Agmar''s Hammer in the woods east of the camp, and only two of its guards came back alive. The arms must be recovered from the Nerubians before the ceremony of initiation can begin.', 'quest 11977 description (your emissary); quest 11978 description (armaments lost when a caravan from Agmar''s Hammer was ambushed; officially bring these taunka into the Horde); quest 11980 description (Roh''kill and Tor''zin barely escaped)'),
(6530, 3, 65, 2, 0, 13, 'The Stolen Ley Lines', 'On the morning the land of the western Dragonblight shook and tore apart, the Kirin Tor took notice. Images of Archmage Modera at Stars'' Rest and Archmage Aethas Sunreaver at Agmar''s Hammer summoned help in all haste, sure the upheaval would have broader repercussions than troubling the natives. Its source was Moonrest Gardens, a ley line nexus. The blue dragonflight had used a device called a surge needle to destroy it, freeing its power to be redirected at their will, and the archmages want to know where that power is going.', 'quests 11995 and 11996 descriptions and reward text (the upheaval this morning; broader repercussions); quests 12000 and 11999 descriptions (Moonrest a ley line nexus; the surge needle destroyed it to redirect the power)'),
(6531, 3, 65, 3, 1, 13, 'Naxxramas and the Fall of Wintergarde', 'Lord Fordragon led a crushing assault against the Lich King''s forces at the Wrathgate, and the Lich King answered by sending Naxxramas down upon Wintergarde. While Kel''Thuzad hides in the floating citadel, his ground commander, Thel''zan the Duskbringer, lays siege to the keep. The lower village is already lost, and every minute lessens the chance of pulling survivors from its ruins. High Commander Halford Wyrmbane needs every soldier he has, and gryphon riders are going out over the Carrion Fields to snatch up whoever still lives.', 'quest 12235 description; warcraft.wiki.gg/wiki/Wintergarde_Keep'),
(6532, 3, 65, 4, 1, 13, 'The Forgotten Tale', 'Zelig the Visionary hears the cries of the fallen echo across Northrend from his tower at Wintergarde Keep. Arthas left a terrible imprint on everything he touched, he says, and only wither and decay remain in his wake. Zelig holds that the past must be studied so the enemy can be better known, for untold truths might surface that could help the Alliance''s campaign. First, though, his scrying orb must be recovered from the town hall in Wintergarde''s embattled town square.', 'quest 12282 description and reward text'),
(6533, 3, 65, 5, 2, 13, 'The Forsaken Blight', 'After an eternity of failure the plaguebringers of New Agamand have perfected their blight, and a specimen has come by bat to Chief Plaguebringer Middleton at Venomspite, who rejoices at the whole field of Scourge waiting beyond the mountain. At Agmar''s Hammer, Doctor Sintar Malefious waits for it impatiently, calling it a Horde imperative, the last piece of the victory puzzle. First it must be made safe to handle. Middleton has synthesized an inert strain; mixed with a reactive agent, it would turn anyone near it into a shapeless pile of goo.', 'quest 12181 description (Harris: an eternity of failure; perfection); quest 12182 reward text; quest 12189 description and reward text (Horde imperative; the last piece of the victory puzzle; handlers vaporized); quest 12188 description (an inert strain; with a reactive agent we''d be goo)'),
(6534, 3, 65, 6, 2, 13, 'The Spy in New Hearthglen', 'High Executor Wroth of Venomspite has decreed death for every member of the Scarlet Onslaught, the most zealous of the old Crusade, now dug in at New Hearthglen to the south. No quarter is offered, and any of his own taken by the humans will be left to their fate. Before Venomspite strikes, Spy Mistress Repine means to learn what the Onslaught is planning: its daily orders, from the abbey, the barracks and the beach, are to be stolen and put in her hands.', 'quest 12205 description (Wroth''s decree); quest 12209 description (the most zealous of the Scarlet Crusade); quest 12234 description; quest 12488 description and reward text'),
(6535, 3, 65, 7, 0, 13, 'The Battle for the Wrathgate', 'At Angrathar the Wrathgate the Alliance and the Horde stand side by side. Highlord Bolvar Fordragon holds Fordragon Hold and Saurfang the Younger the Kor''kron Vanguard, and together they have pressed the Scourge hard. But the Scourge does not relent. Frost wyrms strafe the field from above, and no advance on the gate itself is possible while they fly. They are made from the bones of ancient dragons, so before anyone defiles those bones, the dragon queen at Wyrmrest must give her leave.', 'quest 12224 reward text (Horde: we gain ground each day; once we stop the skeletal dragons, Highlord Fordragon and I will take the field); quest 12495 description (Alliance: our assault has staggered the Scourge, but they remain unrelenting; frost wyrms strafe the field; permission before defiling the bones); quest 12496 description (Horde: until the strafing is halted we cannot move forward; permission first); quest 12474 description (Fordragon Hold, our base of operations)');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(6501, 1, 0, 255, 'Icemist is no more. The Scourge has fallen upon the taunka, and what fills these tents is all that remains of the taunka of the Borean Tundra and the Dragonblight: a broken people, battered and brought to the brink of extinction, whom the Horde means to nurse back to health so that they may strengthen it in turn.', 'quest 11930 reward text (Icemist is no more; 11977 requires 11930); quests 11977 and 11979 reward text (all that remains of the taunka; the Horde will nurse them back to health); quest 11979 description (the Scourge seized Icemist)'),
(6502, 1, 0, 255, 'The wolvar raids were stopped the hard way. Loguhn, the Render of Flesh, alpha of the Snowfall Glade tribe, was slain before his hovel on the glade''s northern rise, and his blood was worn back to Ko''nani as a sign of dominance and respect. The tribe now fights over his place, and the elder judges that it will have to be enough.', 'quest 11959 description and reward text'),
(6502, 2, 0, 255, 'Toalu''u the Mystic sought the Kalu''ak''s destiny from Oacha''noa, the sea goddess, called up with the Pearl of the Depths on the Briny Pinnacle. Her answer was that the Kalu''ak must stand with the outsiders. All souls are one with the magic of the world, the mystic says, and if the blue dragons win control of it, all are doomed. Elder Ko''nani accepts it, for weal or woe.', 'quest 12032 description and reward text'),
(6502, 3, 0, 255, 'Old Tua''kea the fisherman lost his crab traps to something far larger than a shark: Tu''u''gwar, He Who Plays With Food, his ancient nemesis, back in the harbor. Baited with the flesh of Kili''ua, the mother of all crabs from her island to the southwest, the beast took the hook and died, and Tua''kea is spreading the news to every Kalu''ak.', 'quests 12011, 12016, 12017 descriptions and reward text'),
(6503, 1, 0, 255, 'Elder Mana''loa told what happened. The sacred ground of the elves to the west was torn asunder, and its magic now runs through the land, ruining what it touches. The power came up through the lake and killed most of the village in an instant; those who survived were driven mad. He asked that the lingering spirits be set free to move on, and that the deranged living be left alone, for they may yet find their wits again.', 'quest 12031 description; quest 12030 reward text; quest 12028 reward text (ghosts and gibbering madness)'),
(6503, 2, 0, 255, 'The lake held one more secret. At its bottom lay the commander of the mage hunters and the forces around him, killed not by drowning but by the elementals that rose from the rents in the lake bed when they summoned their ley line focus there. The mage hunters were the architects of their own demise.', 'quest 12098 and 12106 reward text'),
(6504, 1, 0, 255, 'When the sorcerers bored their pit they let something loose: Arcanimus, a monstrosity that fed on the spirits of the dead. With Arcanimus destroyed, Ethenial gave a warning to carry to whoever would listen. By blowing apart the ley line anchor beneath the gardens, the blue dragonflight threatens to destroy them all.', 'quest 12013 description and reward text'),
(6504, 2, 0, 255, 'Not every mage hunter served willingly. On the Glittering Strand fell Captain Emmy Malin, and a letter in her robes told her father, Archmage Malin of Stormwind, that she had been forced to work for Malygos''s armies under threat to her family, and was sabotaging them from within. At Stars'' Rest, Commander Saia Azuresteel promised to see the letter delivered to him.', 'quest 12067 description and reward text; zone_areas 4225: Captain Emmy Malin 26762'),
(6505, 1, 0, 255, 'Courier Lanson, sent out from the Borean Tundra, reached Stars'' Rest badly hurt. Anub''ar had ambushed him as he crossed the bridge into the Dragonblight, and they had known he was coming. He carries a list that must reach High Commander Halford Wyrmbane at Wintergarde Keep: the names of traitors in the Alliance''s ranks. If any of them serve at Wintergarde, he warns, it could be catastrophic.', 'quest 12157 description and reward text; quest 12171 description'),
(6506, 1, 0, 255, 'Most of the ancients could still be saved. Fed the bark of the treants, who are immune to the magic, three of them were strengthened, and both camps took note. Sarendryana of Stars'' Rest means to speak with them and ask for the Alliance''s sake; Earthwarden Grife of Agmar''s Hammer hopes to win them for the Horde, or at least to make them think twice about attacking it.', 'quests 12092 and 12096 descriptions, completion and reward text'),
(6507, 1, 0, 255, 'The Pit runs straight down to Azjol-Nerub, and the Horde feared the Anub''ar would use it to flank its army at the Wrathgate. So it struck first: a Warsong battle standard was planted in the middle of Icemist and held against all who came to tear it down. The Anub''ar were crushed by land, and the Horde vowed to crush them next by air.', 'quest 12036 description and reward text (12053 requires 12036); quest 12053 description and reward text (crushed by land, soon by air); quest 12072 (requires 12071, which requires 12053)'),
(6507, 2, 0, 255, 'Among the servants of the Anub''ar was High Cultist Zangus, who led their cultists in the Scourge''s service. Both the Horde and the Alliance learned that he had gone to ground in the Pit of Narjun, and both marked him for death. He was slain there, and with their master gone his followers could be hunted down and the land left to recover.', 'quest 12056 description and reward text (Horde: working with the Scourge; hiding in the Pit); quests 12168 and 12169 descriptions and reward text (Alliance: the leader of the cultists; in the Pit; his forces mopped up)'),
(6508, 1, 0, 255, 'The taunka have come to the Hammer. Armed by the Horde at Westwind, the refugees have made the trek east, and now taunka soldiers stand guard among the orcs. With them came Greatmother Icemist, who bears the name of the taunka''s fallen village.', 'spell_area 46997 (area 4165, from DONE 11978; See Taunka Invisibility, type 7) and creature_addon aura 46996 on every Taunka Soldier 26437 and on Greatmother Icemist 26652 (one spawn); quest 11978 completion and reward text (Horde arms; their trek to Agmar''s Hammer)'),
(6508, 2, 0, 255, 'Roanauk Icemist, High Chief of the taunka, now walks the Hammer among his people. Freed from the Anub''ar prison at Icemist, he thanks those who rescued him and swears he will never forget their courage and determination.', 'spell_area 47418 (area 4165, from DONE 12069) and creature_template_addon aura 47417 (Roanauk Icemist 26810); npc_text 12721'),
(6508, 3, 0, 255, 'Captain Gort was brought a tome bound in flesh, written in the tongue of the Scourge, and only Koltira could read it. The death knight asked a price first: power for his runeblade, Byfrost, and a battle with the shadows that torment him. His translation named members of the Cult of the Damned across the whole continent, among them orcs Gort had known for years.', 'quests 12057, 12115, 12132 descriptions and reward text; quest 12136 description and reward text'),
(6509, 1, 0, 255, 'The queen abhors the loss of any life, but she will not let Malygos defile the temple. She named Lord Afrasastrasz commander of its defenses. From its middle terrace he sends riders out on Wyrmrest defenders to fight the blue dragons and drakes in the air, and to strike at the eruption of ley line energy at the Azure Dragonshrine, whose stolen power has emboldened the blues to attack the temple itself.', 'quest 12435 description; quest 12372 description (offered at the 12435 turn-in: emboldened by the magic flowing through the Azure Dragonshrine); npc_text 12887 (Afrasastrasz: the ley line anchor''s power redirected to the Azure Dragonshrine)'),
(6509, 2, 0, 255, 'Aurastrasza of the red flight saw another danger the others missed. The magnataur of the wastes, who seldom gather without killing one another, had come together under a single warlord, carrying horns marked with a hammer and a lightning bolt. His name was won from the runemaster Dregmar Runebrand: Grom''thar the Thunderbringer. Called out with his own horn to the ring of torches south of the Azure Dragonshrine, he fell, and the magnataur were left to fight among themselves again.', 'quests 12146-12151 descriptions and reward text'),
(6509, 3, 17, 255, 'Beneath the temple lies the Ruby Sanctum, a home of the red dragonflight. Something terrible has happened there: its entry lies in ruins, its guardians have been violently slain, and the scouts sent to learn more have not returned. Krasus fears the worst.', 'quests 26012 and 26013 descriptions (QuestSortID 4987, used as sources only)'),
(6510, 1, 0, 255, 'Red dragons still fall in the battle overhead. To spare them from joining the emberwyrms, ruby acorns from the shrine''s tree were planted beside their bodies, returning them to the earth, where they can give new life: a proud fate for any of their kind.', 'quests 12417 and 12449 descriptions and reward text'),
(6510, 2, 0, 255, 'Dahlia was found beneath the shrine. The Scourge had turned her into the source of its corruption, and only in death was she freed. Her lingering spirit told of falling at the feet of a death knight named Bloodbane, and warned that the Lich King now treads on the most sacred lands of every flight to force the dragons to act. The red dragons who heard it wondered what her fall means for the younger races, if one so devoted could be corrupted.', 'quests 12418 and 12450 descriptions and reward text; creature_text 27683 (Remnant of Dahlia Suntouch)'),
(6511, 1, 0, 255, 'The cult meant to make the black dragons its own. In the back of the Maw, Rothin the Decaying was raising the dead of Serinar''s brood as magmawyrms, fed by necromantic runes drawn on the cave floor. The runes were stamped out, the bones in the summoning chamber were burned with Neltharion''s Flame so that none could toy with them again, and Rothin was destroyed. Serinar relished every scream.', 'quests 12263, 12264, 12265 descriptions and reward text; quest 12267 description and reward text'),
(6512, 1, 0, 255, 'Nishera fears for the Dreamer. A horrible nightmare has taken hold in the Emerald Dream, and when she asked Ysera to help fight the Scourge raising frost wyrms at the other shrines, Ysera misunderstood and told the shrine''s defenders to treat all who are not green dragons as enemies. The shrine has lost its balance, and its skytalons must be thinned to restore it.', 'quest 12454 description'),
(6512, 2, 0, 255, 'Even that was not enough. Alystros, the immense skytalon who keeps the shrine''s aerial defenses, would not listen to reason and had to be slain. Nishera bids no one weep for him: he has given his eternal life to the shrine''s defense and will be reborn, free, she hopes, of the confusion of the Emerald Nightmare that grips the Dreamer.', 'quest 12456 description and reward text'),
(6512, 3, 0, 255, 'Lord Itharius, the green ambassador at Wyrmrest, knows another of the shrine''s properties: any unliving creature that steps into it falls to dust, save the Forsaken. Seeds of its lashers proved it, gravely weakening a reanimated frost wyrm, Turgid the Vile of the Carrion Fields and Overseer Deathgaze of Jintha''kalar. He means to ask Ysera''s leave to use them, if she can be coaxed from her nightmare.', 'quests 12458 and 12459 descriptions and reward text'),
(6513, 1, 0, 255, 'The hourglass did not reveal the Infinite Dragonflight''s leader. It showed something Chromie found better: Nozdormu, the Lord of Time, alive and fighting the Infinite himself. No one had known where or when he had gone, only that he had disappeared to deal with very important matters.', 'quest 12470 reward text; spell_area 50012 (Nozdormu visible in 4175 while 12470 is complete)'),
(6515, 1, 0, 255, 'Ko''char never trusted the green runt. He fought his own war, and it ended in the Ice Heart Cavern with the death of Rattlebore, the jormungar spawnmother, a name gifted to her by an adventurer from the Plaguelands. The giant judged that some little ones have nobler intentions than goblins, and pointed the way north to Crystalsong, a cursed and dangerous place.', 'quests 12079 and 12080 descriptions and reward text; npc_text 12707 (the goblin runt cannot be trusted)'),
(6516, 1, 0, 255, 'When Wintergarde was saved, Lord Fordragon came back to Angrathar to prepare his forces for the destruction of the Wrathgate, and the hold grew busier for it: captains of Stormwind now stand among its soldiers.', 'quest 12473 reward text; spell_area 46999 (area 4169, from DONE 12473) and creature_template_addon aura 46998 (Stormwind Captain 27544)'),
(6516, 2, 0, 255, 'The Highlord had a find to share. The strange ore uncovered in the Wintergarde Mine is exactly what the Wrathgate is made of, and he means to find its weakness and expose it for all to see.', 'quest 12474 reward text'),
(6516, 3, 0, 255, 'After the battle at the Wrathgate the hold fell quiet. Highlord Fordragon did not come back to it. Soldiers who lived through the day straggle back from the gate in flight, and the camp he built waits without its commander.', 'spell_area 58932 (Post-Wrath Gate Phase, phase 2, areas 4169-4172 from DONE 12499/12500); creature 31310, 31313 Fleeing Alliance Soldier (phase 2 only); Bolvar 27872 phase 1 only; stormwind.json 151905 part 3 (his body never found)'),
(6517, 1, 0, 255, 'The elder Saurfang sent a secret letter to Agmar''s Hammer, slipped past the Overlord''s readers by a messenger. The Horde''s forces in Northrend serve under young Hellscream, he wrote, and every victory gives Hellscream''s savage tactics more justification, leading the Horde back toward a dark place. So he sent his son to command at the Wrathgate, his heart and strength where he could not be, hoping the young orc''s honor would be noticed and followed.', 'quest 12033 description; item 35941 Letter from Saurfang, page_text 3069'),
(6517, 2, 0, 255, 'After the battle the Vanguard was left without its commander. Saurfang the Younger led the Kor''kron to the front line and did not return, and Horde soldiers who survived the day stream back from the gate in flight.', 'quest 12500 reward text (I will now lead the Kor''kron to the front line); spell_area 58932 (phase 2 from DONE 12499/12500); creature 31328, 31330 Fleeing Horde Soldier (phase 2 only); Saurfang the Younger 25257 phase 1 only'),
(6518, 1, 0, 255, 'Since the battle the field before the gate has fallen strangely still. The dead of the Scourge, the Alliance and the Horde lie where they fell, and Alexstrasza the Life-Binder and her consort Korialstrasz have come down from Wyrmrest to stand before the Wrathgate, looking over what remains.', 'spell_area 58932 and 60778 (areas 4171/4172 from DONE 12499/12500); creature 31333 Alexstrasza and 31334 Korialstrasz, phase 2 only, area 4172; warcraft.wiki.gg/wiki/Battle_of_Angrathar_the_Wrathgate (she arrives after the battle with Korialstrasz); creature_template_addon 31285-31308 ((Wrathgate) soldiers and monsters, phase 2 only: stand state dead, aura 29266)'),
(6519, 1, 0, 255, 'The Wintergarde Mine held a strange ore, and the Scourge now works it with the miners it has raised, to fuel its war machines. Slinkin the demo-gnome, sent in to learn more, died there, but the note in his hand told what he had overheard: the Scourge call the ore saronite, and speak the name Yogg-Saron with great contempt. His last wish was that both entrances be blown shut, so the evil inside could never get out.', 'quest 12275 reward text (the strange ore of Wintergarde Mine); quest 12276 reward text (Slinkin''s note); quest 12277 description (offered from Slinkin''s body at the 12276 turn-in) and reward text'),
(6520, 1, 0, 255, 'Venomspite cut off the Onslaught''s retreat. Burning water brewed from the Forsaken blight set the Sinner''s Folly''s sails ablaze from the dock, and while the deckhands fought the fire, Captain Shely''s rutters were taken from his cabin. Without them, the Onslaught has nowhere to run.', 'quest 12243 description and reward text'),
(6521, 1, 0, 255, 'Wroth knows the instruments of his trade. The rod of compulsion taken from the Onslaught''s torturer was familiar to him from his youth, when he served as a torturer in the court of King Terenas of Lordaeron, and he put it to use at once on the Onslaught''s own officers.', 'quest 12271 reward text; quest 12273 description'),
(6523, 1, 0, 255, 'The news of the ley lines explained a puzzle. She had wondered why the blue dragonflight dared to attack the temple so boldly, and now she knew: they are using enormous amounts of the very magic they claim is a threat to Azeroth. Hypocritical, she said, but so be it. If Malygos will not come to his senses, the Accord has no choice but to act.', 'quests 12123 and 12124 reward text'),
(6523, 2, 0, 255, 'She cannot loose the full fury of the red dragonflight against the Scourge while her flight is entrenched in the war with Malygos. But the bravery of mortals never fails to astound her, rising to challenge death''s cold stare, and it is why their kind is so loved, and so hated. To those who fight, she gives her blessing.', 'quest 12497 description and reward text'),
(6524, 1, 0, 255, 'The ruby brooch of Dahlia Suntouch came back to him from the fallen shrine. He grieved that she had been taken by the Scourge, and resolved to find a new keeper once the shrine is retaken. The Ruby Dragonshrine is sacred to his flight, he said, and the sacrifices made there will not be forgotten. He promised to call upon the one who brought the brooch one day.', 'quest 12419 description, completion and reward text'),
(6525, 1, 0, 255, 'One letter amused him. A troll mage hunter, Lieutenant Ta''zinni, died with a note to his sister Deino in his robes: he had been forced to serve Malygos''s armies under threat to his family, and was sabotaging them from within. Agmar laughed at it and called him a traitor. Yet he had known Deino once, a troll with honor, and promised she would learn her brother''s fate, without learning who killed him. In return, he told the messenger, he owned them now.', 'quest 12085 description, completion and reward text'),
(6526, 1, 0, 255, 'Kilix knows the odds: there are thousands of the Anub''ar, spilling out of every dark crevice in Northrend, and no one stands a chance against them alone. Together, perhaps. As a gesture of good faith he sent Overlord Agmar a scroll setting out the strengths and weaknesses of the Nerubians attacking Icemist, and the overlord saw in it the means to crush the Anub''ar assault.', 'quest 12040 reward text; quest 12041 description and reward text'),
(6527, 1, 0, 255, 'The list of traitors carried to Wintergarde came to him too late to matter, and he crumpled it up. The people named on it, he said, could be found near the front gate: they were the ones hanging from the arches as ghoul bait.', 'quests 12174 and 12298 reward text'),
(6528, 1, 0, 255, 'Her journal tells how it began. A voice came to her in dreams, whispering ''Come to me'', and she knew it for the Holy Light. Her breath misted in the warm sun as it spoke. A vision bade her take the most faithful and abandon the rest of the Crusade, and though she called herself a coward for it, she obeyed. Stepping onto the beach in Northrend, she planted her banner and proclaimed the Crimson Dawn: the Scarlet Crusade was no more, and the Scarlet Onslaught was born.', 'page_text 3092-3149 (items 37931 The Path of Redemption and 37540 The Diary of High General Abbendis both show page 3092)'),
(6528, 2, 0, 255, 'Then a visitor came. Admiral Barean Westwind, who by all accounts had died on these shores an age ago, appeared at her door looking far too young for it, claiming the Light had kept him alive and sent him to be her advisor. Her men took to him with zeal, the high abbot took up a new blessing from him, and some of the men became raven priests. Abbendis could not make herself trust him, and the Light had fallen silent.', 'page_text 3150-3155 (the diary''s later pages)'),
(6528, 3, 0, 255, 'She was struck down in New Hearthglen with her men around her. Westwind watched, urging her on, and when she fell he told her she had served her purpose, promised her killers a meeting in Icecrown and was gone. Her head was carried away as proof of her death.', 'quests 12464 and 12285 (her head the proof); creature_text 27951 groups 0, 2, 3 (Westwind during the fight)'),
(6529, 1, 0, 255, 'With Horde arms to lift their spirits, the taunka were ready. Each spoke the sacred words of the blood oath of the Horde, scroll in hand, and swore to give all they had to drive the Scourge from the world. They had nothing left, Brighthoof said; now they had purpose, and with purpose came hope. The new members of the Horde marched east to Agmar''s Hammer.', 'quests 11978, 11983 descriptions and reward text; quest 12008 description'),
(6529, 2, 0, 255, 'Greatmother Icemist''s son Banthok went west alone in search of his father, and found him alive. High Chief Roanauk Icemist hung in magical chains in the middle of the fallen village, held by a prison whose key the Anub''ar had split among three of their magi.', 'quests 12063 and 12064 descriptions and reward text'),
(6529, 3, 0, 255, 'The key was taken from the magi and the chains fell away. Freed, Roanauk wept over what had been done to his people, called on his fallen brothers to rise and fight once more, and took wing on the winds to bring down Under-King Anub''et''kan. A fragment of the Under-King''s husk went to Overlord Agmar as proof.', 'quest 12069 description and reward text; creature_text 26654 groups 1-7; creature_text 26608'),
(6529, 4, 0, 255, 'Like the tauren, the Forsaken, the trolls and the blood elves, Agmar said, the taunka need a leader of their own blood. At Agmar''s Hammer, before his gathered people, Roanauk read the blood oath and swore himself a weapon of the Warchief''s command, for the Horde and for his taunka brothers and sisters. Agmar welcomed the High Chief into the Horde and promised they would walk together.', 'quest 12140 description and reward text; creature_text 26810 groups 0-5; creature_text 26379 groups 0-2; npc_text 12722'),
(6530, 1, 0, 255, 'The plans taken from the dead mage hunters showed the blue dragonflight seeking an accord with the Ethereum, the ethereals, who could be a powerful ally for Malygos and his madness. Wind Trader Mu''fah and the blue dragon Goramosh, who were to settle it in the gardens, were slain, but too late: Goramosh had let slip that the accord was already reached.', 'quests 12000 and 11999 reward text (12004 and 12005 require them); quests 12004 and 12005 descriptions and reward text; creature_template 26349 Goramosh (type 2, dragonkin)'),
(6530, 2, 0, 255, 'A device carried by Goramosh led to the top of the Surge Needle, and there hung a projection of the Arcanomicon, a map of every ley line intersection in the world. The blue flight uses it to find and destroy the anchors of the ley lines and send their power to the Nexus. But here the path of destruction ran east, when it should have run west.', 'quests 12055, 12059, 12060, 12061 descriptions and reward text'),
(6530, 3, 0, 255, 'Ley line foci, guarded by mage hunters on the Glittering Strand and atop the Lothalor Woodlands, carried the power on, and their control devices imprinted their secrets on whoever used them. The power was being purposefully changed, and used to empower the blue forces, but only at the end of the line, wherever that was. The trail led on to Lake Indu''le.', 'quests 12065, 12066, 12083, 12084 descriptions and reward text'),
(6530, 4, 0, 255, 'Orders on the drowned commander, from someone named Sidragos, moved every mage hunter east to the Azure Dragonshrine. The last focus, under Lake Indu''le, gave up its secrets, and from the shrine''s western ledge the end of the line could be seen: the stolen power had been run beneath the land to the Azure Dragonshrine. The archmages saw at once what they should have guessed all along, and sent word that Wyrmrest must be warned.', 'quests 12107 and 12110 descriptions and reward text; page_text 3073 and 3074 (the Letter of Introduction, items 36832/36833, given on accepting 12119/12122, which are offered at the 12107/12110 turn-in: the power run through foci under the land to the Azure Dragonshrine)'),
(6531, 1, 0, 255, 'Gryphon riders swept low over the Carrion Fields, once the village below the keep, and plucked helpless villagers from among the Scourge. Those who were saved were put back to work fortifying Wintergarde, and Halford hopes it will soon be strong enough to send reinforcements to Lord Fordragon at the Wrathgate.', 'quest 12237 description and reward text; quest 12251 description and reward text (offered at the 12237 turn-in)'),
(6531, 2, 0, 255, 'The dead were rising inside the walls as well, from the town crypt where nobles who died in Northrend were laid to rest. From the necrolord''s chamber at its core came a flesh-bound tome, and Inquisitor Hallard preached at the ghoul who had been Wintergarde''s mayor, Godfrey Goodard, until he talked. Beneath the old village, Godfrey revealed, lay a mausoleum, and there Thel''zan hid and sent a thousand thousand corpses against the keep.', 'quests 12311, 12312, 12319, 12320 descriptions; quest 12321 description and reward text; creature_text 27316, 27577 (the sermon)'),
(6531, 3, 0, 255, 'Steam tanks broke through to the mausoleum. There the rogue Plunderbeard had died with his journal: Thel''zan, he suspected, had once been one of them, and his phylactery could be found. The torn pages told the rest. The phylactery was carried by a great frost wyrm, Icestorm, and the hunt for her led to the 7th Legion Front.', 'quests 12326, 12463, 12465 descriptions and reward text; quest 12466 (Chasing Icestorm, offered at the 12465 turn-in) and 12467'),
(6531, 4, 0, 255, 'With the phylactery before the gateway, Thel''zan was drawn out of hiding. He boasted that without him Naxxramas might never have returned to Northrend. Lord Fordragon himself named him: Father Inigo Montoy, once a cleric of the Argent Dawn, who became what he hated most. Thel''zan fell, Wintergarde was saved, and Fordragon returned to Angrathar.', 'quests 12472 and 12473 descriptions and reward text; creature_text 27383 groups 0-3; creature_text 27858 (Bolvar at the fight)'),
(6532, 1, 0, 255, 'The orb pointed south, to an atrocity committed long ago on the Forgotten Shore. There, at Dawn''s Reach, Zelig''s old friend Orik Trueheart of the Argent Crusade brewed an elixir of murkweed that let a living soul walk among the dead. The ghosts did not know the truth, Orik wept: they think Arthas a hero, when it was Arthas who ordered their ships burned and left them to die in this frozen land. Orik was only a lad in the prince''s fleet, and he survived.', 'quests 12287, 12290, 12291 descriptions and reward text; creature_text 27455 groups 1-2 (the ships must be burned)'),
(6532, 2, 0, 255, 'For five years, at Zelig''s bidding, Orik had poured his anger, anxiety and sorrow over that day into a crystal ball. Set in the ruins of his old base, it let the forgotten see the world through his heart, and hundreds of lost souls were redeemed.', 'quests 12301 and 12305 descriptions and reward text'),
(6532, 3, 0, 255, 'After the betrayal on the shore, Arthas went in search of Frostmourne with Muradin Bronzebeard at his side. A map taken from the Scarlet Onslaught marked a cave by that name near Scarlet Point, and at its bottom Zelig''s orb showed the past: Arthas taking up the cursed blade against Muradin''s warnings, and Muradin struck down, waking with no memory of who he was. Muradin might yet live, Zelig dared to hope, and King Bronzebeard had to be told at once.', 'quest 12475 description and reward text; quest 12478 description and reward text; creature_text 27455 groups 3-7, 27480 groups 0-5 (the vision in Frostmourne Cavern)'),
(6533, 1, 0, 255, 'The reactive agent came from the dead: ectoplasm of the Alliance specters haunting the beach to the south. The shell for the blight came from the Emerald Dragonshrine: the hardened tears that green dragons weep before they die.', 'quests 12188 and 12200 descriptions and reward text'),
(6533, 2, 0, 255, 'Naxxramas offered the test. A blight bomb dropped from a Forsaken blight spreader fell on the hungering dead streaming out of old Wintergarde, and they were destroyed. Middleton declared the test a success, though it irritated him that it may have helped the Alliance.', 'quest 12200 reward text; quest 12218 description and reward text'),
(6533, 3, 0, 255, 'The final specimen went to Agmar''s Hammer with instructions for its preparation and samples of the reactive agent. Malefious found it glorious, exactly to specifications, and warned the courier to keep everything they had seen to themselves: the work is classified.', 'quest 12221 description and reward text'),
(6534, 1, 0, 255, 'The Forsaken found a strange thing. Their perfected blight, said to kill everything it touched, did nothing to a captured Onslaught soldier. Something protects them, and Apothecary Vicky Levine, horrified, had to fall back on starving rats to keep their priests from raising the dead.', 'quests 12206 and 12211 descriptions, completion and reward text'),
(6534, 2, 0, 255, 'Repine had an agent inside the town all along: Agent Skully, disguised by magic as the Onslaught''s cemetery caretaker. The stolen orders hinted that something was imminent, but first the Onslaught''s strange protection had to be explained. Skully traced it to a newly scribed blessing at the back of Bishop Street''s prayer book, written in the high abbot''s own hand.', 'quest 12239 description and reward text (12254 requires 12239); quest 12254 description and reward text'),
(6534, 3, 0, 255, 'The Onslaught''s torturer, LeCraft, had bled secrets out of every Forsaken his people caught, and Wroth wanted them back. Under the high executor''s own branding iron LeCraft broke: the Onslaught knew a spy hid among them disguised as one of their own, and a grand admiral named Westwind had somehow given the high abbot the prayer that kept them safe from the blight. Wroth had never heard the name.', 'quest 12252 description and reward text; creature_text 27209 groups 4-5'),
(6534, 4, 0, 255, 'Wearing the stolen image of a raven priest, Skully''s helper rang the abbey bell to draw off High Abbot Landgren''s guards and was led aside to speak with him. He saw through the disguise at once. The Master sees all, he said, and he would not die by their hand: he leapt from the abbey to his death, promising to return if the grand admiral willed it.', 'quests 12260 and 12274 descriptions and reward text; creature_text 27439 groups 0-5'),
(6534, 5, 0, 255, 'The general''s own diary held bad news: an attack was imminent, and Wroth ordered the head of the Scarlet Onslaught brought to him, literally. When it came, he laughed and dared them to raise her without it. Venomspite was saved, though the grand admiral got away.', 'quest 12283 reward text; quest 12285 description, completion and reward text'),
(6535, 1, 0, 255, 'Alexstrasza warned that the wyrms were the least of their concerns. North of Wyrmrest lie the dying grounds of Galakrond, progenitor of dragonkind, from whom the titans created the Aspects, a beast larger than all the Aspects combined. The Scourge is digging up his bones, and Grand Necrolord Antiok commands the work from atop the Wicked Coil. Should the Scourge raise Galakrond, everything the armies at the gate have done would be for naught.', 'quests 12495 and 12496 reward text; quest 12497 description'),
(6535, 2, 0, 255, 'On the back of a Wyrmrest vanquisher, a champion of the Accord burned the scavengers at Galakrond''s Rest and struck down Antiok on the Wicked Coil, taking the scythe with which he controlled the wyrms. The queen declared that the deed had saved the armies at the gate from certain death, and had it recorded for posterity.', 'quest 12498 description and reward text'),
(6535, 3, 0, 255, 'Bolvar and Saurfang the Younger led their armies against the gate together. The Lich King came out to meet them, Frostmourne in hand, promising the justice of the grave. Saurfang charged him, and the blade shattered his axe and slew him in a single stroke, taking his soul. Bolvar stood his ground.', 'quests 12499 and 12500 reward text; warcraft.wiki.gg/wiki/Battle_of_Angrathar_the_Wrathgate (the cinematic)'),
(6535, 4, 0, 255, 'Then Grand Apothecary Putress appeared on the heights above, crying that the Forsaken had not forgotten or forgiven, and his catapults rained plague on the field: death to the Scourge, and death to the living. Scourge, Alliance and Horde fell alike, and the Lich King himself staggered and withdrew behind his gate. The red dragonflight came down and burned the plague away, and with it the field, and Bolvar Fordragon fell amid the fire.', 'warcraft.wiki.gg/wiki/Battle_of_Angrathar_the_Wrathgate (Putress''s words, the plague, the Lich King falling to his knees and retreating, the red flight incinerating the plague); stormwind.json 151905 part 3 and undercity.json 149704 (consistent telling)'),
(6535, 5, 0, 255, 'Saurfang''s battle armor was carried from the field to his father at Warsong Hold. The old orc looked to the heavens. Like Brox, he said, his son died a hero, and for an orc there could be no better end. The armor would be placed on his pyre at the Ancestral Grounds of Nagrand, and Varok turned his mind to more pressing matters.', 'quest 13242 description, completion and reward text');
